/**
 * The semantic oneof for [`super::SubscriptionStart`].
 */
sealed class Start {
    
    /**
     * Start at the exact stream cursor, including cursor zero.
     */
    data class Cursor(
        val v1: kotlin.ULong) : Start()
        
    {
        

        companion object
    }
    
    /**
     * Start at the service's current head, preserving the wire boolean.
     */
    data class CurrentHead(
        val v1: kotlin.Boolean) : Start()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeStart : FfiConverterRustBuffer<Start>{
    override fun read(buf: ByteBuffer): Start {
        return when(buf.getInt()) {
            1 -> Start.Cursor(
                FfiConverterULong.read(buf),
                )
            2 -> Start.CurrentHead(
                FfiConverterBoolean.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Start) = when(value) {
        is Start.Cursor -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.v1)
            )
        }
        is Start.CurrentHead -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: Start, buf: ByteBuffer) {
        when(value) {
            is Start.Cursor -> {
                buf.putInt(1)
                FfiConverterULong.write(value.v1, buf)
                Unit
            }
            is Start.CurrentHead -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





